import type { Direction, StrategyResult } from './types';

/**
 * Deriv synthetic-index digits are generated by a pseudo-random number generator
 * designed to produce independent, uniformly distributed outcomes.
 *
 * The following strategies are heuristic statistical filters describing patterns in
 * historical sample noise (such as sample variance, runs, or sample skew).
 * Because these strategies operate on the same stream of ticks, their outputs are
 * correlated. Past tick distributions do not alter future probabilities or guarantee edge.
 */

export const STRATEGY_MIN_OBSERVATIONS = {
    frequency: 100,
    recency: 100,
    streak: 30,
    momentum: 150,
    skew: 100,
    transitions: 150,
    gaps: 100,
    cycles: 100,
} as const;

export const THRESHOLDS = {
    zMatch: 2,
    zDiff: -1,
    streakMin: 3,
    momentumZDiff: -2,
    skewChiSquare: 16.92,
    transitionsMinSuccessors: 20,
    gapMin: 29,
    cycleZMin: 3,
} as const;

export interface DecideFromZResult {
    direction: Direction;
    digit: number;
    strength: number;
    z: number;
}

/**
 * Shared decision rule from z-scores:
 * - p = 0.1, z = (count - n * p) / sqrt(n * p * (1 - p))
 * - hottest digit with z >= zMatch (default 2) -> MATCHES (strength z/4)
 * - coldest digit with z <= zDiff (default -1) -> DIFFERS (strength -z/3)
 * - If both qualify, larger strength wins; ties go to MATCHES
 * - Ties between digits go to the lowest digit
 */
export function decideFromZ(
    countsOrZ: readonly number[],
    nOrOptions?: number | { zMatch?: number; zDiff?: number },
    maybeOptions?: { zMatch?: number; zDiff?: number }
): DecideFromZResult | null {
    let zScores: number[];
    let zMatch: number = THRESHOLDS.zMatch;
    let zDiff: number = THRESHOLDS.zDiff;

    if (typeof nOrOptions === 'number') {
        const n = nOrOptions;
        if (maybeOptions?.zMatch !== undefined) zMatch = maybeOptions.zMatch;
        if (maybeOptions?.zDiff !== undefined) zDiff = maybeOptions.zDiff;

        const p = 0.1;
        const expected = n * p;
        const variance = n * p * (1 - p);
        const stdDev = Math.sqrt(variance);

        if (stdDev <= 0) return null;

        zScores = new Array(10);
        for (let d = 0; d < 10; d++) {
            zScores[d] = (countsOrZ[d] - expected) / stdDev;
        }
    } else {
        zScores = countsOrZ as number[];
        if (nOrOptions?.zMatch !== undefined) zMatch = nOrOptions.zMatch;
        if (nOrOptions?.zDiff !== undefined) zDiff = nOrOptions.zDiff;
    }

    let hottestDigit = 0;
    let maxZ = -Infinity;
    for (let d = 0; d < 10; d++) {
        if (zScores[d] > maxZ) {
            maxZ = zScores[d];
            hottestDigit = d;
        }
    }

    let coldestDigit = 0;
    let minZ = Infinity;
    for (let d = 0; d < 10; d++) {
        if (zScores[d] < minZ) {
            minZ = zScores[d];
            coldestDigit = d;
        }
    }

    const matchQualifies = maxZ >= zMatch;
    const diffQualifies = minZ <= zDiff;

    if (!matchQualifies && !diffQualifies) {
        return null;
    }

    const matchStrength = matchQualifies ? Math.min(1, Math.max(0, maxZ / 4)) : -1;
    const diffStrength = diffQualifies ? Math.min(1, Math.max(0, -minZ / 3)) : -1;

    if (matchQualifies && diffQualifies) {
        if (diffStrength > matchStrength) {
            return {
                direction: 'DIFFERS',
                digit: coldestDigit,
                strength: diffStrength,
                z: minZ,
            };
        }
        return {
            direction: 'MATCHES',
            digit: hottestDigit,
            strength: matchStrength,
            z: maxZ,
        };
    }

    if (diffQualifies) {
        return {
            direction: 'DIFFERS',
            digit: coldestDigit,
            strength: diffStrength,
            z: minZ,
        };
    }

    return {
        direction: 'MATCHES',
        digit: hottestDigit,
        strength: matchStrength,
        z: maxZ,
    };
}

/** Strategy 1: Frequency (whole-window counts) */
export function frequencyStrategy(digits: readonly number[]): StrategyResult {
    const minObs = STRATEGY_MIN_OBSERVATIONS.frequency;
    if (digits.length < minObs) {
        return {
            id: 'frequency',
            name: 'Frequency',
            status: 'ineligible',
            reason: `Needs at least ${minObs} observations (have ${digits.length})`,
        };
    }

    const counts = new Array(10).fill(0);
    for (let i = 0; i < digits.length; i++) {
        counts[digits[i]]++;
    }

    const decision = decideFromZ(counts, digits.length);
    if (!decision) {
        return {
            id: 'frequency',
            name: 'Frequency',
            status: 'abstain',
            reason: `All digit counts within normal threshold (${digits.length} ticks evaluated)`,
        };
    }

    const count = counts[decision.digit];
    return {
        id: 'frequency',
        name: 'Frequency',
        status: 'signal',
        direction: decision.direction,
        digit: decision.digit,
        strength: decision.strength,
        reason:
            decision.direction === 'MATCHES'
                ? `Hottest digit ${decision.digit} appeared ${count} times in ${digits.length} ticks (z = ${decision.z.toFixed(2)} >= 2.0)`
                : `Coldest digit ${decision.digit} appeared ${count} times in ${digits.length} ticks (z = ${decision.z.toFixed(2)} <= -1.0)`,
    };
}

/** Strategy 2: Recency (exponentially weighted shares, half-life 50 ticks) */
export function recencyStrategy(digits: readonly number[]): StrategyResult {
    const minObs = STRATEGY_MIN_OBSERVATIONS.recency;
    if (digits.length < minObs) {
        return {
            id: 'recency',
            name: 'Recency',
            status: 'ineligible',
            reason: `Needs at least ${minObs} observations (have ${digits.length})`,
        };
    }

    const n = digits.length;
    let sumW = 0;
    let sumW2 = 0;
    const weightedCounts = new Array(10).fill(0);

    for (let i = 0; i < n; i++) {
        const age = n - 1 - i;
        const w = Math.pow(0.5, age / 50);
        sumW += w;
        sumW2 += w * w;
        weightedCounts[digits[i]] += w;
    }

    const nEff = (sumW * sumW) / sumW2;
    const effCounts = weightedCounts.map((w) => (w / sumW) * nEff);

    const decision = decideFromZ(effCounts, nEff);
    if (!decision) {
        return {
            id: 'recency',
            name: 'Recency',
            status: 'abstain',
            reason: `Recency weighted shares within normal range (effective N = ${nEff.toFixed(1)})`,
        };
    }

    const sharePercent = ((weightedCounts[decision.digit] / sumW) * 100).toFixed(1);
    return {
        id: 'recency',
        name: 'Recency',
        status: 'signal',
        direction: decision.direction,
        digit: decision.digit,
        strength: decision.strength,
        reason:
            decision.direction === 'MATCHES'
                ? `Recent weighted share for digit ${decision.digit} is ${sharePercent}% (effective N = ${nEff.toFixed(1)}, z = ${decision.z.toFixed(2)} >= 2.0)`
                : `Recent weighted share for digit ${decision.digit} is ${sharePercent}% (effective N = ${nEff.toFixed(1)}, z = ${decision.z.toFixed(2)} <= -1.0)`,
    };
}

/** Strategy 3: Streak (run of the last digit >= 3) */
export function streakStrategy(digits: readonly number[]): StrategyResult {
    const minObs = STRATEGY_MIN_OBSERVATIONS.streak;
    if (digits.length < minObs) {
        return {
            id: 'streak',
            name: 'Streak',
            status: 'ineligible',
            reason: `Needs at least ${minObs} observations (have ${digits.length})`,
        };
    }

    const n = digits.length;
    const lastDigit = digits[n - 1];
    let run = 0;
    for (let i = n - 1; i >= 0; i--) {
        if (digits[i] === lastDigit) {
            run++;
        } else {
            break;
        }
    }

    if (run >= THRESHOLDS.streakMin) {
        const strength = Math.min(1, Math.max(0, (run - 2) / 3));
        return {
            id: 'streak',
            name: 'Streak',
            status: 'signal',
            direction: 'MATCHES',
            digit: lastDigit,
            strength,
            reason: `Last digit ${lastDigit} repeated ${run} consecutive times (run >= 3)`,
        };
    }

    return {
        id: 'streak',
        name: 'Streak',
        status: 'abstain',
        reason: `Current run of last digit ${lastDigit} is ${run} (< 3)`,
    };
}

/** Strategy 4: Momentum (last 50 vs previous 100 ticks, two-proportion z per digit, decideFromZ with +2 / -2) */
export function momentumStrategy(digits: readonly number[]): StrategyResult {
    const minObs = STRATEGY_MIN_OBSERVATIONS.momentum;
    if (digits.length < minObs) {
        return {
            id: 'momentum',
            name: 'Momentum',
            status: 'ineligible',
            reason: `Needs at least ${minObs} observations (have ${digits.length})`,
        };
    }

    const n = digits.length;
    const n1 = 50;
    const n2 = 100;

    const c1 = new Array(10).fill(0);
    for (let i = n - n1; i < n; i++) {
        c1[digits[i]]++;
    }

    const c2 = new Array(10).fill(0);
    for (let i = n - n1 - n2; i < n - n1; i++) {
        c2[digits[i]]++;
    }

    const zScores = new Array(10).fill(0);
    for (let d = 0; d < 10; d++) {
        const p1 = c1[d] / n1;
        const p2 = c2[d] / n2;
        const pPool = (c1[d] + c2[d]) / (n1 + n2);
        if (pPool <= 0 || pPool >= 1) {
            zScores[d] = 0;
        } else {
            const se = Math.sqrt(pPool * (1 - pPool) * (1 / n1 + 1 / n2));
            zScores[d] = (p1 - p2) / se;
        }
    }

    const decision = decideFromZ(zScores, {
        zMatch: THRESHOLDS.zMatch,
        zDiff: THRESHOLDS.momentumZDiff,
    });

    if (!decision) {
        return {
            id: 'momentum',
            name: 'Momentum',
            status: 'abstain',
            reason: `No significant shift between last 50 and previous 100 ticks (thresholds +2.0 / -2.0)`,
        };
    }

    const pRecent = (c1[decision.digit] / n1) * 100;
    const pPrior = (c2[decision.digit] / n2) * 100;
    return {
        id: 'momentum',
        name: 'Momentum',
        status: 'signal',
        direction: decision.direction,
        digit: decision.digit,
        strength: decision.strength,
        reason:
            decision.direction === 'MATCHES'
                ? `Digit ${decision.digit} momentum surge: ${pRecent.toFixed(0)}% in last 50 vs ${pPrior.toFixed(0)}% in prior 100 (z = ${decision.z.toFixed(2)} >= 2.0)`
                : `Digit ${decision.digit} momentum drop: ${pRecent.toFixed(0)}% in last 50 vs ${pPrior.toFixed(0)}% in prior 100 (z = ${decision.z.toFixed(2)} <= -2.0)`,
    };
}

/** Strategy 5: Skew (chi-square vs uniform; if >= 16.92 -> DIFFERS on rarest digit) */
export function skewStrategy(digits: readonly number[]): StrategyResult {
    const minObs = STRATEGY_MIN_OBSERVATIONS.skew;
    if (digits.length < minObs) {
        return {
            id: 'skew',
            name: 'Skew',
            status: 'ineligible',
            reason: `Needs at least ${minObs} observations (have ${digits.length})`,
        };
    }

    const counts = new Array(10).fill(0);
    for (let i = 0; i < digits.length; i++) {
        counts[digits[i]]++;
    }

    const E = digits.length / 10;
    let chiSquare = 0;
    for (let d = 0; d < 10; d++) {
        chiSquare += Math.pow(counts[d] - E, 2) / E;
    }

    if (chiSquare >= THRESHOLDS.skewChiSquare) {
        let rarestDigit = 0;
        let minCount = Infinity;
        for (let d = 0; d < 10; d++) {
            if (counts[d] < minCount) {
                minCount = counts[d];
                rarestDigit = d;
            }
        }

        const strength = Math.min(1, Math.max(0, (chiSquare - THRESHOLDS.skewChiSquare) / THRESHOLDS.skewChiSquare));
        return {
            id: 'skew',
            name: 'Skew',
            status: 'signal',
            direction: 'DIFFERS',
            digit: rarestDigit,
            strength,
            reason: `Chi-square is ${chiSquare.toFixed(2)} (>= 16.92, df=9); rarest digit ${rarestDigit} appeared ${minCount} times (expected ${E.toFixed(1)})`,
        };
    }

    return {
        id: 'skew',
        name: 'Skew',
        status: 'abstain',
        reason: `Chi-square is ${chiSquare.toFixed(2)} (< 16.92, df=9)`,
    };
}

/** Strategy 6: Transitions (digits that followed past occurrences of the last digit) */
export function transitionsStrategy(digits: readonly number[]): StrategyResult {
    const minObs = STRATEGY_MIN_OBSERVATIONS.transitions;
    if (digits.length < minObs) {
        return {
            id: 'transitions',
            name: 'Transitions',
            status: 'ineligible',
            reason: `Needs at least ${minObs} observations (have ${digits.length})`,
        };
    }

    const n = digits.length;
    const current = digits[n - 1];
    const successors: number[] = [];

    for (let i = 0; i < n - 1; i++) {
        if (digits[i] === current) {
            successors.push(digits[i + 1]);
        }
    }

    if (successors.length < THRESHOLDS.transitionsMinSuccessors) {
        return {
            id: 'transitions',
            name: 'Transitions',
            status: 'ineligible',
            reason: `Needs at least ${THRESHOLDS.transitionsMinSuccessors} successors (have ${successors.length})`,
        };
    }

    const succCounts = new Array(10).fill(0);
    for (let i = 0; i < successors.length; i++) {
        succCounts[successors[i]]++;
    }

    const decision = decideFromZ(succCounts, successors.length);
    if (!decision) {
        return {
            id: 'transitions',
            name: 'Transitions',
            status: 'abstain',
            reason: `Transition distribution following digit ${current} within normal range (${successors.length} successors)`,
        };
    }

    const count = succCounts[decision.digit];
    return {
        id: 'transitions',
        name: 'Transitions',
        status: 'signal',
        direction: decision.direction,
        digit: decision.digit,
        strength: decision.strength,
        reason:
            decision.direction === 'MATCHES'
                ? `Digit ${decision.digit} followed ${current} ${count} of ${successors.length} times (z = ${decision.z.toFixed(2)} >= 2.0)`
                : `Digit ${decision.digit} followed ${current} only ${count} of ${successors.length} times (z = ${decision.z.toFixed(2)} <= -1.0)`,
    };
}

/** Strategy 7: Gaps (ticks since each digit last appeared; longest gap >= 29 -> MATCHES) */
export function gapsStrategy(digits: readonly number[]): StrategyResult {
    const minObs = STRATEGY_MIN_OBSERVATIONS.gaps;
    if (digits.length < minObs) {
        return {
            id: 'gaps',
            name: 'Gaps',
            status: 'ineligible',
            reason: `Needs at least ${minObs} observations (have ${digits.length})`,
        };
    }

    const n = digits.length;
    const lastSeen = new Array(10).fill(-1);
    for (let i = 0; i < n; i++) {
        lastSeen[digits[i]] = i;
    }

    let longestGap = -1;
    let targetDigit = 0;
    for (let d = 0; d < 10; d++) {
        const gap = lastSeen[d] === -1 ? n : n - 1 - lastSeen[d];
        if (gap > longestGap) {
            longestGap = gap;
            targetDigit = d;
        }
    }

    if (longestGap >= THRESHOLDS.gapMin) {
        const strength = Math.min(1, Math.max(0, longestGap / 60));
        return {
            id: 'gaps',
            name: 'Gaps',
            status: 'signal',
            direction: 'MATCHES',
            digit: targetDigit,
            strength,
            reason: `Digit ${targetDigit} has not appeared for ${longestGap} ticks (gap >= 29)`,
        };
    }

    return {
        id: 'gaps',
        name: 'Gaps',
        status: 'abstain',
        reason: `Longest gap is ${longestGap} ticks for digit ${targetDigit} (< 29)`,
    };
}

/** Strategy 8: Cycles (periods 2-12, z of self-match rate vs 10%; best z >= 3 -> MATCHES digits[n - period]) */
export function cyclesStrategy(digits: readonly number[]): StrategyResult {
    const minObs = STRATEGY_MIN_OBSERVATIONS.cycles;
    if (digits.length < minObs) {
        return {
            id: 'cycles',
            name: 'Cycles',
            status: 'ineligible',
            reason: `Needs at least ${minObs} observations (have ${digits.length})`,
        };
    }

    const n = digits.length;
    let bestPeriod = 2;
    let bestZ = -Infinity;
    let bestMatches = 0;
    let bestTotal = 0;

    for (let period = 2; period <= 12; period++) {
        const N = n - period;
        let matches = 0;
        for (let i = period; i < n; i++) {
            if (digits[i] === digits[i - period]) {
                matches++;
            }
        }
        const expected = N * 0.1;
        const stdDev = Math.sqrt(N * 0.1 * 0.9);
        const z = (matches - expected) / stdDev;
        if (z > bestZ) {
            bestZ = z;
            bestPeriod = period;
            bestMatches = matches;
            bestTotal = N;
        }
    }

    if (bestZ >= THRESHOLDS.cycleZMin) {
        const predictedDigit = digits[n - bestPeriod];
        const strength = Math.min(1, Math.max(0, bestZ / 6));
        return {
            id: 'cycles',
            name: 'Cycles',
            status: 'signal',
            direction: 'MATCHES',
            digit: predictedDigit,
            strength,
            reason: `Period ${bestPeriod} self-match rate z = ${bestZ.toFixed(2)} (>= 3.0, ${bestMatches}/${bestTotal} matches); predicted digit is ${predictedDigit}`,
        };
    }

    return {
        id: 'cycles',
        name: 'Cycles',
        status: 'abstain',
        reason: `Best cycle period is ${bestPeriod} with z = ${bestZ.toFixed(2)} (< 3.0)`,
    };
}

export const STRATEGIES: readonly ((digits: readonly number[]) => StrategyResult)[] = [
    frequencyStrategy,
    recencyStrategy,
    streakStrategy,
    momentumStrategy,
    skewStrategy,
    transitionsStrategy,
    gapsStrategy,
    cyclesStrategy,
];
